import { test, expect } from '@playwright/test';

test.describe('Accessibility checks for Saucedemo', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('Login fields have non-empty placeholder attributes', async ({ page }) => {
    const usernameInput = page.getByLabel('Username');
    const passwordInput = page.getByLabel('Password');

    const usernamePlaceholder = await usernameInput.getAttribute('placeholder');
    const passwordPlaceholder = await passwordInput.getAttribute('placeholder');

    expect(usernamePlaceholder).not.toBeNull();
    expect(usernamePlaceholder).not.toBe('');
    expect(passwordPlaceholder).not.toBeNull();
    expect(passwordPlaceholder).not.toBe('');
  });

  test('Product images have non-empty alt attributes after login', async ({ page }) => {
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');

    const productImages = await page.locator('.inventory_item img.inventory_item_img');

    const altAttributes = await productImages.evaluateAll(images => images.map(img => img.alt));

    altAttributes.forEach(alt => {
      expect(alt).not.toBeNull();
      expect(alt).not.toBe('');
    });
  });
});
